// Página de chat (rota GET /): um único HTML que conversa pelo POST /chat.
// O desenho aprovado está em docs/desenhos/pagina-canvas.html. Dois ajustes pedidos na
// aprovação: no celular o rodapé fica no fim da área que rola, e o hover só existe em
// aparelho com mouse.
//
// A linha seguinte é a fonte Inter (SIL Open Font License 1.1), subconjunto latino,
// variável de 400 a 800, em WOFF2 e base64. Ela vai embutida para a página não depender
// de terceiros nem de um segundo arquivo. É uma linha só, de 44 KB: pule ao ler.
const INTER_WOFF2_BASE64 = "";

/**
 * Diz se o corpo devolvido pelo POST /chat é uma resposta do agente. Qualquer outra
 * coisa vira o estado de erro da página. Roda no navegador (o texto desta função é
 * copiado para dentro do HTML), por isso não pode usar nada de fora dela.
 */
export function lerResposta(corpo: unknown): { reply: string; handoff: boolean } | null {
  if (!corpo || typeof corpo !== "object") return null;
  const { reply, handoff } = corpo as Record<string, unknown>;
  if (typeof reply !== "string" || reply.trim() === "" || typeof handoff !== "boolean") return null;
  return { reply, handoff };
}

// String.raw: as barras invertidas do CSS e do JavaScript abaixo chegam ao navegador como
// estão escritas. O texto não pode conter crase nem cifrão seguido de chave.
export const PAGINA = String.raw`<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Concierge · imóveis de temporada</title>
<style>
  @font-face {
    font-family: "Inter Pagina";
    font-style: normal;
    font-weight: 400 800;
    font-display: swap;
    src: url(data:font/woff2;base64,${INTER_WOFF2_BASE64}) format("woff2");
  }

  /* ---------- Tokens ---------- */
  :root {
    color-scheme: light;
    --fundo: #fafafa;
    --texto: #141414;
    --suave: #5e5e5e;
    --fio: #d4d4d4;
    --grade: #e3e3e3;
    --destaque: #2b4bff;
    --sobre-destaque: #ffffff;

    --fonte: "Inter Pagina", ui-sans-serif, system-ui, sans-serif;
    --t-rotulo: 12px;
    --t-pequeno: 14px;
    --t-corpo: 16px;
    --t-titulo: 28px;
    --t-titulo-celular: 22px;
    --t-chamada: clamp(24px, 3vw, 36px);
    --entrelinha: 1.6;
    --entrelinha-titulo: 1.15;
    --aperto: -0.025em;
    --largo: 0.12em;
    --largo-compacto: 0.08em;

    --e1: 4px;
    --e2: 8px;
    --e3: 12px;
    --e4: 16px;
    --e6: 24px;
    --e8: 32px;
    --e12: 48px;

    --alvo: 44px;
    --ponto: 6px;
    --trilho: 360px;
    --pagina: 1200px;
    --coluna-rotulo: 144px;
    --largura-enviar: 136px;
    --medida: 62ch;
    --margem: var(--e8);
    --rapido: 150ms;
  }
  @media (max-width: 820px) {
    :root { --margem: var(--e4); --largura-enviar: 120px; }
  }

  /* ---------- Base ---------- */
  *, *::before, *::after { box-sizing: border-box; }
  html, body { margin: 0; }
  body {
    background: var(--fundo);
    color: var(--texto);
    font-family: var(--fonte);
    font-size: var(--t-corpo);
    line-height: var(--entrelinha);
    -webkit-font-smoothing: antialiased;
  }
  h1, h2, p, ul { margin: 0; padding: 0; }
  ul { list-style: none; }
  button, textarea { font: inherit; color: inherit; border-radius: 0; }
  a { color: inherit; text-underline-offset: 3px; }
  :focus-visible { outline: 2px solid var(--texto); outline-offset: 3px; }

  /* ---------- Primitivos ---------- */
  .rotulo {
    font-size: var(--t-rotulo);
    line-height: var(--e4);
    font-weight: 500;
    letter-spacing: var(--largo);
    text-transform: uppercase;
    color: var(--suave);
  }
  .selo { display: inline-block; padding: var(--e1) var(--e2); background: var(--texto); color: var(--fundo); }
  .botao {
    min-height: var(--alvo);
    padding: 0 var(--e6);
    border: 1px solid var(--texto);
    background: var(--texto);
    color: var(--fundo);
    font-size: var(--t-rotulo);
    font-weight: 600;
    letter-spacing: var(--largo);
    text-transform: uppercase;
    cursor: pointer;
    transition: background var(--rapido), color var(--rapido);
  }
  .botao.contorno { background: transparent; color: var(--texto); }
  .botao:disabled { background: var(--grade); border-color: var(--grade); color: var(--suave); cursor: not-allowed; }
  .campo {
    display: block;
    width: 100%;
    min-height: var(--alvo);
    max-height: calc(var(--e6) * 5 + var(--e6));
    padding: calc(var(--e2) + 1px) var(--e3);
    border: 1px solid var(--texto);
    background: var(--fundo);
    font-size: var(--t-corpo);
    line-height: var(--e6);
    resize: none;
    field-sizing: content;
    overflow-y: auto;
  }
  .campo::placeholder { color: var(--suave); opacity: 1; }
  .campo:focus-visible { position: relative; z-index: 1; }

  /* ---------- Casca ---------- */
  .pagina {
    display: grid;
    height: 100vh;
    height: 100dvh;
    max-width: var(--pagina);
    margin-inline: auto;
    border-inline: 1px solid var(--grade);
    grid-template-columns: var(--trilho) minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    grid-template-areas:
      "topo     conversa"
      "exemplos conversa"
      "rodape   envio";
  }
  .principal { display: contents; }
  .pular {
    position: absolute;
    left: var(--e3);
    top: var(--e3);
    z-index: 2;
    padding: var(--e3) var(--e4);
    background: var(--texto);
    color: var(--fundo);
    font-size: var(--t-pequeno);
  }
  .pular:not(:focus) { clip-path: inset(50%); width: 1px; height: 1px; overflow: hidden; padding: 0; }
  .topo { grid-area: topo; padding: var(--e8) var(--margem) var(--e12); border-right: 1px solid var(--grade); }
  .topo h1 { font-size: var(--t-titulo); line-height: 1.1; font-weight: 800; letter-spacing: var(--aperto); }
  .topo .rotulo { margin-top: var(--e2); }

  /* ---------- Exemplos ---------- */
  .exemplos { grid-area: exemplos; border-right: 1px solid var(--grade); }
  .exemplos h2 { padding: 0 var(--margem) var(--e3); }
  .exemplo {
    display: block;
    width: 100%;
    min-height: var(--alvo);
    padding: var(--e4) var(--margem);
    border: 0;
    border-top: 1px solid var(--fio);
    background: transparent;
    text-align: left;
    cursor: pointer;
    transition: background var(--rapido), color var(--rapido);
  }
  .exemplos li:last-child .exemplo { border-bottom: 1px solid var(--fio); }
  .exemplo .rotulo { display: block; transition: color var(--rapido); }
  .exemplo .ex-texto { display: block; margin-top: var(--e1); font-size: var(--t-pequeno); line-height: 1.5; }
  .exemplo:focus-visible { outline-offset: -4px; }
  .exemplo:disabled { color: var(--suave); background: var(--grade); border-color: var(--fio); cursor: not-allowed; }

  /* ---------- Conversa ---------- */
  .conversa {
    grid-area: conversa;
    position: relative;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  .conversa:focus-visible { outline-offset: -2px; }
  .entrada { padding: var(--e12) var(--margem); }
  .entrada h2 {
    max-width: 20ch;
    font-size: var(--t-chamada);
    line-height: var(--entrelinha-titulo);
    font-weight: 800;
    letter-spacing: var(--aperto);
  }
  .entrada p { max-width: 52ch; margin-top: var(--e6); color: var(--suave); }
  .entrada .rotulo { margin-top: var(--e8); color: var(--texto); }

  .turno {
    display: grid;
    grid-template-columns: var(--coluna-rotulo) minmax(0, 1fr);
    column-gap: var(--e6);
    row-gap: var(--e2);
    padding: var(--e6) var(--margem);
    border-top: 1px solid var(--fio);
  }
  .turno:first-child { border-top: 0; padding-top: var(--e8); }
  .turno > .rotulo { padding-top: var(--e1); }
  .turno[data-de="agente"] > .rotulo { color: var(--texto); }
  .turno .texto { max-width: var(--medida); white-space: pre-wrap; overflow-wrap: anywhere; }
  .turno[data-de="voce"] .texto { font-weight: 600; }
  .turno .nota { display: block; margin-top: var(--e1); color: var(--suave); font-size: var(--t-pequeno); font-weight: 400; }
  .turno .cru { display: block; margin-top: var(--e1); text-transform: none; letter-spacing: 0; }
  .turno.aviso { border-top: 0; background: var(--destaque); color: var(--sobre-destaque); }
  .turno.aviso > .rotulo { color: var(--sobre-destaque); }
  .turno.aviso .texto { font-weight: 500; }
  .turno.aviso + .turno { border-top: 0; }
  .turno.erro .texto { font-weight: 500; }
  .turno.erro .botao { display: block; margin-top: var(--e4); }
  /* Abaixo de 1100px a coluna de texto ficaria estreita: o rótulo sobe para cima da fala. */
  @media (max-width: 1100px) {
    .turno { grid-template-columns: minmax(0, 1fr); }
    .turno > .rotulo { padding-top: 0; }
  }

  .pontos { display: inline-flex; gap: var(--e1); margin-left: var(--e2); vertical-align: middle; }
  .pontos i { width: var(--ponto); height: var(--ponto); background: var(--texto); animation: pulso 1.2s infinite both; }
  .pontos i:nth-child(2) { animation-delay: 0.2s; }
  .pontos i:nth-child(3) { animation-delay: 0.4s; }
  @keyframes pulso { 0%, 80%, 100% { opacity: 0.2; } 40% { opacity: 1; } }
  @media (prefers-reduced-motion: reduce) {
    .pontos i { animation: none; }
    * { transition: none !important; }
  }

  /* ---------- Envio ---------- */
  .envio { grid-area: envio; padding: var(--e4) var(--margem) var(--e6); border-top: 1px solid var(--texto); background: var(--fundo); }
  .envio label { display: block; margin-bottom: var(--e2); color: var(--texto); }
  .envio-linha { display: flex; align-items: flex-end; }
  .envio-linha .campo { flex: 1; min-width: 0; }
  .envio-linha .botao { flex: none; min-width: var(--largura-enviar); }
  .dica { margin-top: var(--e2); font-size: var(--t-rotulo); line-height: var(--e4); color: var(--suave); }

  /* ---------- Rodapé: no trilho (telas largas) ou no fim da conversa (celular) ---------- */
  .rodape {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: var(--e4) var(--margem) var(--e3);
    font-size: var(--t-pequeno);
    line-height: 1.5;
    color: var(--suave);
  }
  .rodape a { display: inline-block; padding-block: var(--e3); color: var(--texto); }
  .rodape-trilho { grid-area: rodape; border-right: 1px solid var(--grade); }
  .rodape-rolagem { display: none; }
  .nq { white-space: nowrap; }

  /* ---------- Celular ---------- */
  @media (max-width: 820px) {
    .pagina {
      border-inline: 0;
      grid-template-columns: minmax(0, 1fr);
      grid-template-rows: auto auto minmax(0, 1fr) auto;
      grid-template-areas: "topo" "exemplos" "conversa" "envio";
    }
    .topo {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: var(--e4);
      padding: var(--e4) var(--margem) var(--e3);
      border-right: 0;
    }
    .topo h1 { font-size: var(--t-titulo-celular); }
    .topo .rotulo { margin-top: 0; }
    .exemplos { border-right: 0; border-bottom: 1px solid var(--texto); }
    .exemplos h2 { padding-bottom: var(--e2); }
    .exemplos li:last-child .exemplo { border-bottom: 0; }
    .exemplo { padding-block: var(--e3); }
    /* Com conversa em curso, os exemplos encolhem para uma linha de três rótulos. */
    .tem-conversa .exemplos ul { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }
    .tem-conversa .exemplo { position: relative; padding: 0 var(--e2); text-align: center; border-left: 1px solid var(--fio); }
    .tem-conversa .exemplos li:first-child .exemplo { border-left: 0; }
    .tem-conversa .exemplo .rotulo { color: inherit; letter-spacing: var(--largo-compacto); }
    .tem-conversa .exemplo .ex-texto { position: absolute; width: 1px; height: 1px; margin: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
    .entrada { padding-block: var(--e8); }
    .turno { padding-block: var(--e4); }
    .turno:first-child { padding-top: var(--e6); }
    .envio { padding-block: var(--e3) var(--e4); }
    .envio-linha .botao { padding-inline: var(--e4); }
    .dica[data-so-teclado] { display: none; }
    .rodape-trilho { display: none; }
    .rodape-rolagem {
      display: flex;
      margin-top: auto;
      padding: var(--e6) var(--margem) var(--e4);
      font-size: var(--t-rotulo);
    }
    .rodape-rolagem a { padding-block: var(--e2); }
  }

  /* ---------- Ponteiro em cima: só onde existe mouse ---------- */
  @media (hover: hover) {
    a:hover { text-decoration-thickness: 2px; }
    .botao:hover:not(:disabled) { background: var(--fundo); color: var(--texto); }
    .botao.contorno:hover:not(:disabled) { background: var(--texto); color: var(--fundo); }
    .exemplo:hover:not(:disabled) { background: var(--texto); color: var(--fundo); border-color: var(--texto); }
    .exemplo:hover:not(:disabled) .rotulo { color: var(--fundo); }
    .exemplo:hover:focus-visible { outline-color: var(--fundo); }
  }
  /* fim do hover */

  /* ---------- Pressionado (vale também no toque, só enquanto o dedo está em cima) ---------- */
  .botao:active:not(:disabled),
  .botao.contorno:active:not(:disabled),
  .exemplo:active:not(:disabled) { background: var(--suave); border-color: var(--suave); color: var(--fundo); }
  .exemplo:active:not(:disabled) .rotulo { color: var(--fundo); }
  .exemplo:active:focus-visible { outline-color: var(--fundo); }
</style>
</head>
<body>
<div class="pagina">
  <a class="pular" href="#mensagem">Pular para o campo de mensagem</a>

  <header class="topo">
    <h1>Concierge</h1>
    <p class="rotulo">Imóveis de temporada</p>
  </header>

  <section class="exemplos" aria-labelledby="titulo-exemplos">
    <h2 class="rotulo" id="titulo-exemplos">Exemplos</h2>
    <ul>
      <li><button type="button" class="exemplo" data-exemplo>
        <span class="rotulo">Cotação</span>
        <span class="ex-texto">Quanto fica o GRM-301 de 15/01/2027 a 18/01/2027 para 2 pessoas?</span>
      </button></li>
      <li><button type="button" class="exemplo" data-exemplo>
        <span class="rotulo">Comodidade</span>
        <span class="ex-texto">O GRM-301 tem lareira e hidromassagem?</span>
      </button></li>
      <li><button type="button" class="exemplo" data-exemplo>
        <span class="rotulo">Desconto</span>
        <span class="ex-texto">Consegue um desconto se eu pagar à vista?</span>
      </button></li>
    </ul>
  </section>

  <main class="principal">
    <div class="conversa" id="conversa" tabindex="0" role="region" aria-label="Conversa">
      <div class="entrada" id="entrada">
        <h2>Pergunte sobre um imóvel, peça uma cotação ou registre o seu pedido.</h2>
        <p>O concierge responde só com o que está no catálogo, calcula o total da estadia e, com a sua confirmação, encaminha o pedido ao time comercial. Preço não se negocia aqui: pedido de desconto vai para uma pessoa do time.</p>
        <p class="rotulo">Escreva abaixo ou escolha um exemplo</p>
      </div>
      <div id="registro" role="log" aria-live="polite"></div>
      <footer class="rodape rodape-rolagem">
        <span>Agente de demonstração, dados fictícios.</span>
        <a href="https://github.com/evertonresende/agente-concierge">github.com/evertonresende/<wbr><span class="nq">agente-concierge</span></a>
      </footer>
    </div>

    <form class="envio" id="envio">
      <label class="rotulo" for="mensagem">Sua mensagem</label>
      <div class="envio-linha">
        <textarea class="campo" id="mensagem" rows="1" placeholder="Escreva sua pergunta" enterkeyhint="send" aria-describedby="dica"></textarea>
        <button class="botao" id="enviar" type="submit">Enviar</button>
      </div>
      <p class="dica" id="dica" role="status" data-so-teclado>Enter envia · Shift + Enter quebra a linha</p>
    </form>
  </main>

  <footer class="rodape rodape-trilho">
    <span>Agente de demonstração, dados fictícios.</span>
    <a href="https://github.com/evertonresende/agente-concierge">github.com/evertonresende/<wbr><span class="nq">agente-concierge</span></a>
  </footer>
</div>

<script>
(function () {
  var lerResposta = ${lerResposta.toString()};

  var DICA = 'Enter envia · Shift + Enter quebra a linha';
  var ESPERA_MS = 70000; // o contrato promete resposta em até 60 s
  var ESPACO_QUE_NAO_QUEBRA = String.fromCharCode(160); // o total não se separa do "R$" na quebra de linha
  var raiz = document.documentElement;
  var conversa = document.getElementById('conversa');
  var registro = document.getElementById('registro');
  var formulario = document.getElementById('envio');
  var campo = document.getElementById('mensagem');
  var botao = document.getElementById('enviar');
  var dica = document.getElementById('dica');
  var exemplos = document.querySelectorAll('[data-exemplo]');
  var temMouse = matchMedia('(pointer: fine)').matches;
  var ocupado = false;

  // Um session_id por carga da página: recarregar começa uma conversa nova.
  var sessao = Array.from(crypto.getRandomValues(new Uint8Array(16)), function (b) {
    return ('0' + b.toString(16)).slice(-2);
  }).join('');

  function el(tag, classe, texto) {
    var no = document.createElement(tag);
    if (classe) no.className = classe;
    if (texto != null) no.textContent = texto; // sempre texto, nunca HTML
    return no;
  }
  function turno(de, rotulo, texto, classe) {
    var t = el('div', 'turno' + (classe ? ' ' + classe : ''));
    t.dataset.de = de;
    t.appendChild(el('p', 'rotulo', rotulo));
    t.appendChild(el('div', 'texto', texto));
    return registro.appendChild(t);
  }

  // Rolagem: a posição em que o fim de um turno encosta no fim da área visível.
  function fimDe(no) { return no.offsetTop + no.offsetHeight - conversa.clientHeight; }
  function acompanhando() {
    var ultimo = registro.lastElementChild;
    return !ultimo || conversa.scrollTop >= fimDe(ultimo) - 24;
  }

  function ocupar(sim) {
    ocupado = sim;
    botao.disabled = sim;
    botao.textContent = sim ? 'Enviando' : 'Enviar';
    exemplos.forEach(function (b) { b.disabled = sim; });
    conversa.setAttribute('aria-busy', String(sim));
    dica.textContent = sim ? 'Aguardando a resposta. Pode levar até um minuto.' : DICA;
    if (sim) dica.removeAttribute('data-so-teclado'); else dica.setAttribute('data-so-teclado', '');
  }

  function limparErro() {
    var erro = registro.querySelector('.erro');
    if (erro) erro.remove();
  }

  // fala: o turno do hóspede já na tela, quando é uma nova tentativa da mesma mensagem.
  function enviar(texto, fala) {
    if (ocupado) return;
    limparErro();
    var entrada = document.getElementById('entrada');
    if (entrada) entrada.remove();
    raiz.classList.add('tem-conversa');
    if (fala) fala.querySelector('.nota').remove(); else fala = turno('voce', 'Você', texto);

    var espera = turno('agente', 'Concierge', 'Escrevendo');
    espera.setAttribute('aria-hidden', 'true');
    var pontos = espera.lastChild.appendChild(el('span', 'pontos'));
    pontos.append(el('i'), el('i'), el('i'));
    ocupar(true);
    if (temMouse) campo.focus();
    conversa.scrollTop = fimDe(espera);

    var limite = new AbortController();
    var relogio = setTimeout(function () { limite.abort(); }, ESPERA_MS);
    fetch('/chat', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ session_id: sessao, message: texto }),
      signal: limite.signal
    }).then(function (resposta) {
      return resposta.json();
    }).then(function (corpo) {
      var lida = lerResposta(corpo);
      if (!lida) throw new Error('resposta fora do contrato');
      var seguir = acompanhando();
      espera.remove();
      var resposta = turno('agente', 'Concierge', lida.reply.replace(/R\$ (?=\d)/g, 'R$' + ESPACO_QUE_NAO_QUEBRA));
      if (lida.handoff) {
        var aviso = turno('sistema', 'Encaminhada',
          'Esta conversa foi passada para uma pessoa do time. Você pode continuar escrevendo por aqui.', 'aviso');
        aviso.firstChild.appendChild(el('span', 'cru', 'handoff: true'));
      }
      // Resposta mais alta que a área aparece a partir do começo dela; a que cabe, inteira.
      if (seguir) conversa.scrollTop = Math.min(resposta.offsetTop, fimDe(registro.lastElementChild));
      ocupar(false);
    }).catch(function () {
      espera.remove();
      fala.lastChild.appendChild(el('span', 'nota', 'Sem resposta'));
      var erro = turno('sistema', '', 'A resposta não chegou ou veio incompleta. Você pode tentar de novo.', 'erro');
      erro.firstChild.appendChild(el('span', 'selo', 'Erro'));
      var denovo = erro.lastChild.appendChild(el('button', 'botao contorno', 'Tentar de novo'));
      denovo.type = 'button';
      denovo.addEventListener('click', function () { enviar(texto, fala); });
      ocupar(false);
      conversa.scrollTop = fimDe(erro);
      denovo.focus();
    }).then(function () {
      clearTimeout(relogio);
    });
  }

  // Onde o navegador não faz o campo crescer sozinho (field-sizing), cresce por aqui.
  var cresceSozinho = window.CSS && CSS.supports('field-sizing', 'content');
  function ajustarCampo() {
    if (cresceSozinho) return;
    campo.style.height = 'auto';
    campo.style.height = (campo.scrollHeight + 2) + 'px';
  }
  campo.addEventListener('input', ajustarCampo);

  formulario.addEventListener('submit', function (evento) {
    evento.preventDefault();
    var texto = campo.value.trim();
    if (ocupado || !texto) return;
    campo.value = '';
    ajustarCampo();
    enviar(texto);
  });
  campo.addEventListener('keydown', function (evento) {
    if (evento.key === 'Enter' && !evento.shiftKey && !evento.isComposing) {
      evento.preventDefault();
      formulario.requestSubmit();
    }
  });
  exemplos.forEach(function (b) {
    b.addEventListener('click', function () {
      enviar(b.querySelector('.ex-texto').textContent);
    });
  });

  // No celular o foco inicial abriria o teclado em cima dos exemplos.
  if (temMouse) campo.focus();
})();
</script>
</body>
</html>`;
